mapper.select:

where 1 = 1
and p.visitor_uid like concat('%', #{visitorUid}, '%')
and p.light_tag_code = #{lightTagCode}
and p.space_tag_code = #{spaceTagCode}
and p.budget_level = #{budgetLevel}
and p.pet_preference = #{petPreference}
and p.care_preference = #{carePreference}
and p.last_recommend_time >= #{params.beginTime}
and p.last_recommend_time <= #{params.endTime}
order by p.last_recommend_time desc, p.profile_id desc
